let words: Set<string> | null = null;

/** Is this (lower-case) word a common English word? */
export function isEnglishWord(w: string): boolean {
  if (!words) {
    words = new Set();
    let prev = "";
    for (const item of PACKED.split(" ")) {
      const word = prev.slice(0, Number(item[0])) + item.slice(1);
      words.add(word);
      prev = word;
    }
  }
  return words.has(w);
}
